export default function SectorChip({ sector, size = 88, className = "", label }) {
  const uid = useId().replace(/:/g, "");
  const key = PATTERNS[sector] ? sector : "concrete";
  const u = `${key}-${uid}`;
  const { defs, body } = PATTERNS[key](u);

  return (
    <svg
      viewBox="0 0 200 200"
      width={size}
      height={size}
      className={className}
      role="img"
      aria-label={label ?? `${key} material sample`}
    >
      <defs>
        {defs}
        <filter
          id={`gr${u}`}
          x="0"
          y="0"
          width="100%"
          height="100%"
          colorInterpolationFilters="sRGB"
        >
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="1" seed="9" />
          <feColorMatrix type="saturate" values="0" />
        </filter>
      </defs>
      {body}
      <rect width="200" height="200" filter={`url(#gr${u})`} opacity="0.11" />
    </svg>
  );
}
